// The instance's administration (plan: Instance and control plane). An instance admin is a user whose
// Better Auth role is 'admin' (the admin plugin's; `/api/me` reports it as `is_staff`), apart from the
// organization and workspace roles: it grants no access to anyone's workspaces, only these routes. The
// admin plugin's own endpoints (impersonation, bans, deletion, roles) stay closed to the browser
// (policy.ts BROWSER_ROUTES); admins are named and removed here instead.
//
// First-run setup: the operator's MINERVA_SETUP_KEY (generated by `pnpm secrets` into .env.cloudflare)
// is a one-time capability. Signed in, `POST /api/setup {key}` makes the caller the first admin; the
// claim is a row of D1's `instance_setup` written with the role in one batch, so of concurrent claims
// exactly one wins and a second claim, by anyone, is refused. On an instance whose sign-up is closed the
// same key, sent as `X-Minerva-Setup-Key` to Better Auth's sign-up, admits the operator's own sign-up
// until setup is done (policy.ts); the address is verified as any other's before it can sign in. The
// routes are in instance-routes.ts.

import { MIN_SETUP_KEY_LENGTH, settings } from "../config.ts";
import { digest, timingSafeEqual } from "../lib/hash.ts";

/** The header that admits the operator's sign-up before setup on an instance whose sign-up is closed. */
export const SETUP_KEY_HEADER = "X-Minerva-Setup-Key";

export const INVALID_KEY = "This setup key is not valid.";
export const ALREADY_SET_UP = "This instance is already set up.";
export const ADMINS_ONLY = "Only instance admins can do this.";
export const LAST_ADMIN = "Keep at least one instance admin.";
export const NO_SUCH_USER = "No user has this email address.";

/** A key shorter than this (a misconfiguration) admits nothing (src/config.ts). */
const MIN_KEY_LENGTH = MIN_SETUP_KEY_LENGTH;

/** Whether `key` is the instance's setup key, compared in constant time (as digests, so lengths do not leak). */
export async function setupKeyValid(env: Env, key: string | null | undefined): Promise<boolean> {
	const expected = env.MINERVA_SETUP_KEY ?? "";
	if (expected.length < MIN_KEY_LENGTH || !key) return false;
	return timingSafeEqual(await digest("SHA-256", key), await digest("SHA-256", expected));
}

export async function isSetUp(db: D1Database): Promise<boolean> {
	return (await db.prepare("SELECT 1 AS found FROM instance_setup WHERE id = 1").first()) !== null;
}

/** The admins' sign-up setting; null follows MINERVA_SIGNUP_OPEN. */
export async function signupOverride(db: D1Database): Promise<boolean | null> {
	const row = await db.prepare("SELECT signup_open FROM instance_settings WHERE id = 1").first<{ signup_open: number | null }>();
	return row === null || row.signup_open === null ? null : row.signup_open === 1;
}

/** Whether anyone may sign up: the admins' setting, else MINERVA_SIGNUP_OPEN. */
export async function signupOpen(env: Env): Promise<boolean> {
	return (await signupOverride(env.DB)) ?? settings(env).signupOpen;
}

/**
 * Whether a sign-up request may create an account (policy.ts): sign-up is open, or it carries the setup
 * key and the instance is not set up yet. `headers` is null for our own server code.
 */
export async function signupAllowed(env: Env, headers: Headers | null): Promise<boolean> {
	if (await signupOpen(env)) return true;
	const key = headers?.get(SETUP_KEY_HEADER);
	return (await setupKeyValid(env, key)) && !(await isSetUp(env.DB));
}

/**
 * Claims the setup for `userId` and makes them an admin, in one batch: the claim row is inserted only if
 * none exists, and the role is set only where the row holds this claim. False when setup was claimed before.
 */
export async function claimSetup(db: D1Database, userId: string, now = Date.now()): Promise<boolean> {
	const claim = crypto.randomUUID();
	const [, promoted] = await db.batch([
		db.prepare("INSERT INTO instance_setup (id, claim, user_id, claimed_at) VALUES (1, ?, ?, ?) ON CONFLICT (id) DO NOTHING").bind(claim, userId, now),
		db
			.prepare(`UPDATE "user" SET role = 'admin', "updatedAt" = ? WHERE id = ? AND EXISTS (SELECT 1 FROM instance_setup WHERE id = 1 AND claim = ?)`)
			.bind(new Date(now).toISOString(), userId, claim),
	]);
	return (promoted?.meta.changes ?? 0) > 0;
}
